import urwid
import sys
import os

class LazyFileWalker(urwid.ListWalker):
    def __init__(self, filename):
        self.filename = filename
        self.lines = []
        self.focus = 0
        self.file_size = os.path.getsize(filename)
        self.file = open(filename, 'r+', encoding='utf-8')
        self.line_offsets = [0]
        self._build_offsets()
        self._load_lines()

    def _build_offsets(self):
        # Build line offsets for lazy loading
        self.file.seek(0)
        offset = 0
        while True:
            line = self.file.readline()
            if not line:
                break
            offset += len(line.encode('utf-8'))
            self.line_offsets.append(offset)
        self.file.seek(0)

    def _load_lines(self):
        # Load all lines into memory for editing
        self.file.seek(0)
        self.lines = [line.rstrip('\n') for line in self.file.readlines()]
        if not self.lines:
            self.lines = ['']

    def get_focus(self):
        return self._get_at_pos(self.focus)

    def set_focus(self, position):
        self.focus = position
        self._modified()

    def get_next(self, position):
        if position + 1 >= len(self.lines):
            return None, None
        return self._get_at_pos(position + 1)

    def get_prev(self, position):
        if position <= 0:
            return None, None
        return self._get_at_pos(position - 1)

    def _get_at_pos(self, pos):
        if pos < 0 or pos >= len(self.lines):
            return None, None
        edit = urwid.Edit(edit_text=self.lines[pos])
        urwid.connect_signal(edit, 'change', self._on_edit_change, pos)
        return edit, pos

    def _on_edit_change(self, edit, new_text, pos):
        self.lines[pos] = new_text

    def save(self):
        with open(self.filename, 'w', encoding='utf-8') as f:
            for line in self.lines:
                f.write(line + '\n')

class TextEditor:
    def __init__(self, filename):
        self.walker = LazyFileWalker(filename)
        self.listbox = urwid.ListBox(self.walker)
        self.filename = filename
        self.footer = urwid.Text(
            "Ctrl+S: Save | Ctrl+Q: Quit | Arrows: Move | Enter: New Line | Backspace/Delete: Remove | Ctrl+J: Join Lines"
        )
        self.frame = urwid.Frame(self.listbox, footer=self.footer)
        self.main_loop = urwid.MainLoop(
            self.frame,
            unhandled_input=self.unhandled_input,
            handle_mouse=False
        )
        self.cursor_col = 0

    def run(self):
        self.main_loop.run()

    def unhandled_input(self, key):
        if key == 'ctrl s':
            self.walker.save()
            self.footer.set_text("Saved! Ctrl+S: Save | Ctrl+Q: Quit | Arrows: Move | Enter: New Line | Backspace/Delete: Remove | Ctrl+J: Join Lines")
        elif key == 'ctrl q':
            raise urwid.ExitMainLoop()
        elif key in ('left', 'right', 'enter', 'backspace', 'delete', 'ctrl j'):
            self.handle_edit_key(key)

    def handle_edit_key(self, key):
        focus_widget, focus_pos = self.walker.get_focus()
        if focus_widget is None:
            return
        edit_text = focus_widget.edit_text
        edit_pos = focus_widget.edit_pos

        if key == 'left':
            if edit_pos > 0:
                focus_widget.edit_pos -= 1
            elif focus_pos > 0:
                # Move to end of previous line
                prev_widget, prev_pos = self.walker.get_prev(focus_pos)
                if prev_widget:
                    self.walker.set_focus(prev_pos)
                    prev_widget.edit_pos = len(prev_widget.edit_text)
        elif key == 'right':
            if edit_pos < len(edit_text):
                focus_widget.edit_pos += 1
            elif focus_pos < len(self.walker.lines) - 1:
                # Move to start of next line
                next_widget, next_pos = self.walker.get_next(focus_pos)
                if next_widget:
                    self.walker.set_focus(next_pos)
                    next_widget.edit_pos = 0
        elif key == 'enter':
            # Split line at cursor
            before = edit_text[:edit_pos]
            after = edit_text[edit_pos:]
            self.walker.lines[focus_pos] = before
            self.walker.lines.insert(focus_pos + 1, after)
            self.walker.set_focus(focus_pos + 1)
            self.main_loop.draw_screen()
        elif key == 'backspace':
            if edit_pos > 0:
                # Remove character before cursor
                new_text = edit_text[:edit_pos - 1] + edit_text[edit_pos:]
                self.walker.lines[focus_pos] = new_text
                focus_widget.set_edit_text(new_text)
                focus_widget.edit_pos = edit_pos - 1
            elif focus_pos > 0:
                # Join with previous line
                prev_line = self.walker.lines[focus_pos - 1]
                new_pos = len(prev_line)
                self.walker.lines[focus_pos - 1] += edit_text
                del self.walker.lines[focus_pos]
                self.walker.set_focus(focus_pos - 1)
                prev_widget, _ = self.walker.get_focus()
                prev_widget.set_edit_text(self.walker.lines[focus_pos - 1])
                prev_widget.edit_pos = new_pos
                self.main_loop.draw_screen()
        elif key == 'delete':
            if edit_pos < len(edit_text):
                # Remove character at cursor
                new_text = edit_text[:edit_pos] + edit_text[edit_pos + 1:]
                self.walker.lines[focus_pos] = new_text
                focus_widget.set_edit_text(new_text)
                focus_widget.edit_pos = edit_pos
            elif focus_pos < len(self.walker.lines) - 1:
                # Join with next line
                self.walker.lines[focus_pos] += self.walker.lines[focus_pos + 1]
                del self.walker.lines[focus_pos + 1]
                focus_widget.set_edit_text(self.walker.lines[focus_pos])
                focus_widget.edit_pos = edit_pos
                self.main_loop.draw_screen()
        elif key == 'ctrl j':
            # Join with next line
            if focus_pos < len(self.walker.lines) - 1:
                self.walker.lines[focus_pos] += self.walker.lines[focus_pos + 1]
                del self.walker.lines[focus_pos + 1]
                focus_widget.set_edit_text(self.walker.lines[focus_pos])
                focus_widget.edit_pos = len(self.walker.lines[focus_pos])
                self.main_loop.draw_screen()

def main(filename):
    editor = TextEditor(filename)
    editor.run()

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print("Usage: python text_editor.py <filename>")
        sys.exit(1)
    main(sys.argv[1])
